<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Tokeny API'; ?>
<div class="page-head"><div><p class="eyebrow">Profil</p><h1>Tokeny API</h1><p class="muted">Token ma normalny ACL użytkownika i dodatkowo ograniczone scopes.</p></div></div>
<?php if($newToken):?><div class="alert success token-once"><strong>Skopiuj token teraz. Nie zostanie pokazany ponownie.</strong><code><?=Html::e($newToken['token'])?></code></div><?php endif;?>
<?php if($error):?><div class="alert danger">Nie udało się utworzyć tokena. Sprawdź nazwę, scopes i datę.</div><?php endif;?>
<div class="split"><section class="card"><h2>Nowy token</h2><form method="post" action="<?=Html::e(Url::to('/api-tokens'))?>" class="stack-form"><?=Csrf::field()?><label>Nazwa<input name="name" maxlength="120" required placeholder="Automatyzacja dokumentacji"></label><fieldset><legend>Scopes</legend><?php foreach($scopeOptions as $scope):?><label class="check-label"><input type="checkbox" name="scopes[]" value="<?=Html::e($scope)?>"> <span><?=Html::e($scope)?></span></label><?php endforeach;?></fieldset><label>Wygaśnięcie (opcjonalne)<input type="date" name="expires_at"></label><button class="button">Utwórz token</button></form></section>
<section class="card"><h2>Aktywne i historyczne tokeny</h2><?php if(!$tokens):?><div class="empty-state"><p class="muted">Nie masz tokenów API.</p></div><?php endif;?><?php foreach($tokens as $token):?><div class="list-row"><div><strong><?=Html::e($token['name'])?></strong><small><?=Html::e($token['token_prefix'])?>… · <?=Html::e(implode(', ',$token['scopes']))?><br>utworzony <?=Html::e($token['created_at'])?><?php if($token['expires_at']):?> · wygasa <?=Html::e($token['expires_at'])?><?php endif;?><?php if($token['last_used_at']):?> · użyty <?=Html::e($token['last_used_at'])?><?php endif;?><?php if($token['revoked_at']):?> · unieważniony <?=Html::e($token['revoked_at'])?><?php endif;?></small></div><?php if(!$token['revoked_at']):?><form method="post" action="<?=Html::e(Url::to('/api-tokens/'.$token['id'].'/revoke'))?>"><?=Csrf::field()?><button class="button secondary">Unieważnij</button></form><?php endif;?></div><?php endforeach;?></section></div>
